class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        nums.sort()
        B = max(nums).bit_length()
        ch = [[-1, -1]]
        cnt = [0]

        def update(v, s):
            cur = 0
            for b in range(B - 1, -1, -1):
                d = (v >> b) & 1
                if ch[cur][d] < 0:
                    ch.append([-1, -1])
                    cnt.append(0)
                    ch[cur][d] = len(ch) - 1
                cur = ch[cur][d]
                cnt[cur] += s

        def query(v):
            cur, res = 0, 0
            for b in range(B - 1, -1, -1):
                d = (v >> b) & 1
                nxt = ch[cur][d ^ 1]
                if nxt >= 0 and cnt[nxt] > 0:
                    res |= 1 << b
                    cur = nxt
                else:
                    cur = ch[cur][d]
            return res

        lo = ans = 0
        for v in nums:
            update(v, 1)
            while 2 * nums[lo] < v:
                update(nums[lo], -1)
                lo += 1
            ans = max(ans, query(v))
        return ans

