class Solution {
public:
    int maximumStrongPairXor(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int B = 0;
        while ((1LL << B) <= nums.back()) B++;
        vector<array<int,2>> ch(1, {-1, -1});
        vector<int> cnt(1, 0);
        auto update = [&](int v, int s) {
            int cur = 0;
            for (int b = B - 1; b >= 0; b--) {
                int d = (v >> b) & 1;
                if (ch[cur][d] < 0) {
                    ch.push_back({-1, -1});
                    cnt.push_back(0);
                    ch[cur][d] = ch.size() - 1;
                }
                cur = ch[cur][d];
                cnt[cur] += s;
            }
        };
        auto query = [&](int v) {
            int cur = 0, res = 0;
            for (int b = B - 1; b >= 0; b--) {
                int d = (v >> b) & 1;
                int nxt = ch[cur][d ^ 1];
                if (nxt >= 0 && cnt[nxt] > 0) { res |= 1 << b; cur = nxt; }
                else cur = ch[cur][d];
            }
            return res;
        };
        int lo = 0, ans = 0;
        for (int v : nums) {
            update(v, 1);
            while (2LL * nums[lo] < v) { update(nums[lo], -1); lo++; }
            ans = max(ans, query(v));
        }
        return ans;
    }
};

