class Solution {
    public int maximumStrongPairXor(int[] nums) {
        Arrays.sort(nums);
        int B = 32 - Integer.numberOfLeadingZeros(nums[nums.length - 1]);
        int[][] ch = new int[nums.length * B + 2][2];
        int[] cnt = new int[nums.length * B + 2];
        int size = 1;
        java.util.Arrays.fill(ch[0], -1);
        for (int i = 1; i < ch.length; i++) { ch[i][0] = -1; ch[i][1] = -1; }
        int lo = 0, ans = 0;
        for (int v : nums) {
            int cur = 0;
            for (int b = B - 1; b >= 0; b--) {
                int d = (v >> b) & 1;
                if (ch[cur][d] < 0) { ch[cur][d] = size++; }
                cur = ch[cur][d];
                cnt[cur]++;
            }
            while (2L * nums[lo] < v) {
                int c = 0;
                for (int b = B - 1; b >= 0; b--) {
                    c = ch[c][(nums[lo] >> b) & 1];
                    cnt[c]--;
                }
                lo++;
            }
            cur = 0;
            int res = 0;
            for (int b = B - 1; b >= 0; b--) {
                int d = (v >> b) & 1;
                int nxt = ch[cur][d ^ 1];
                if (nxt >= 0 && cnt[nxt] > 0) { res |= 1 << b; cur = nxt; }
                else cur = ch[cur][d];
            }
            ans = Math.max(ans, res);
        }
        return ans;
    }
}

